PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE metric_points (
	id INTEGER NOT NULL, 
	timestamp DATETIME NOT NULL, 
	request_id VARCHAR(64) NOT NULL, 
	path VARCHAR(128) NOT NULL, 
	latency_ms FLOAT NOT NULL, 
	status_code INTEGER NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE forecast_points (
	id INTEGER NOT NULL, 
	timestamp DATETIME NOT NULL, 
	mode VARCHAR(32) NOT NULL, 
	predicted_rps FLOAT NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE scaling_decisions (
	id INTEGER NOT NULL, 
	timestamp DATETIME NOT NULL, 
	mode VARCHAR(32) NOT NULL, 
	observed_rps FLOAT NOT NULL, 
	predicted_rps FLOAT NOT NULL, 
	desired_replicas INTEGER NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE active_replica_state (
	id INTEGER NOT NULL, 
	active_replicas INTEGER NOT NULL, 
	mode VARCHAR(32) NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE INDEX ix_metric_points_request_id ON metric_points (request_id);
CREATE INDEX ix_metric_points_timestamp ON metric_points (timestamp);
CREATE INDEX ix_forecast_points_timestamp ON forecast_points (timestamp);
CREATE INDEX ix_forecast_points_mode ON forecast_points (mode);
CREATE INDEX ix_scaling_decisions_timestamp ON scaling_decisions (timestamp);
CREATE INDEX ix_scaling_decisions_mode ON scaling_decisions (mode);
COMMIT;
